"""Launch configuration helpers for multi-axis rotary kernels."""

from types import MappingProxyType
from typing import Mapping

# Canonical AOT/runtime inventory. Keys are stable cubin names; values contain
# only the shape fields needed to select and compile that kernel.
MULTIAXIS_ROTARY_TEXT_VARIANTS: Mapping[str, tuple[int, int, int, int]] = (
    MappingProxyType(
        {
            "text_mrope_bf16_h8_kv2_d256_r64": (8, 2, 256, 64),
            "text_mrope_bf16_h16_kv2_d256_r64": (16, 2, 256, 64),
            "text_mrope_bf16_h16_kv4_d256_r64": (16, 4, 256, 64),
            "text_mrope_bf16_h24_kv4_d256_r64": (24, 4, 256, 64),
        }
    )
)
MULTIAXIS_ROTARY_SPATIAL_VARIANTS: Mapping[
    str, tuple[int, int, int, int, str]
] = MappingProxyType(
    {
        "spatial_rope_bf16_h12_d64_r64_a1_cfp32": (12, 64, 64, 1, "float32"),
        "spatial_rope_bf16_h12_d64_r64_a2_cbf16": (12, 64, 64, 2, "bfloat16"),
        "spatial_rope_bf16_h16_d64_r64_a1_cfp32": (16, 64, 64, 1, "float32"),
        "spatial_rope_bf16_h16_d72_r72_a1_cfp32": (16, 72, 72, 1, "float32"),
    }
)

WARP_SIZE = 32
MAX_THREADS_PER_BLOCK = 256


def _rotary_pairs(rotary_dim: int) -> int:
    if rotary_dim % 4 != 0:
        raise ValueError(f"rotary_dim must be divisible by 4, got {rotary_dim}")
    return rotary_dim // 4


def _ceil_power_of_two(value: int) -> int:
    if value < 1:
        raise ValueError(f"value must be positive, got {value}")
    return 1 << ((value - 1).bit_length())


def _launch_threads_for_work_items(work_items: int) -> int:
    """Choose a warp-multiple launch width that covers one block's work."""

    # Tried rounding to a plain warp multiple: Qwen text decode 5.28us vs
    # 5.22us and prefill 8.10us vs 7.78us on H100; keeping power-of-two.
    return max(WARP_SIZE, min(MAX_THREADS_PER_BLOCK, _ceil_power_of_two(work_items)))


def text_heads_per_block(num_heads: int, num_kv_heads: int, rotary_dim: int) -> int:
    total_heads = int(num_heads) + int(num_kv_heads)
    if total_heads < 1:
        raise ValueError(f"total heads must be positive, got {total_heads}")

    max_heads_by_work = max(1, MAX_THREADS_PER_BLOCK // _rotary_pairs(int(rotary_dim)))
    max_heads = min(total_heads, max_heads_by_work)
    for heads_per_block in range(max_heads, 0, -1):
        if total_heads % heads_per_block == 0:
            return heads_per_block
    return 1


def text_launch_threads(
    num_heads: int,
    num_kv_heads: int,
    rotary_dim: int,
    *,
    heads_per_block: int | None = None,
) -> int:
    if heads_per_block is None:
        heads_per_block = text_heads_per_block(num_heads, num_kv_heads, rotary_dim)
    return _launch_threads_for_work_items(int(heads_per_block) * _rotary_pairs(int(rotary_dim)))


def spatial_launch_threads(num_heads: int, rotary_dim: int) -> int:
    return _launch_threads_for_work_items(int(num_heads) * _rotary_pairs(int(rotary_dim)))


__all__ = [
    "MAX_THREADS_PER_BLOCK",
    "MULTIAXIS_ROTARY_TEXT_VARIANTS",
    "MULTIAXIS_ROTARY_SPATIAL_VARIANTS",
    "WARP_SIZE",
    "text_heads_per_block",
    "text_launch_threads",
    "spatial_launch_threads",
]
